//! Small helpers for emitting Rust and Starlark source text.

/// The first line of every generated file.
pub fn generated_marker(profile: &str) -> String {
    format!(
        "// @generated by L2R ({profile}). Do not edit: change the architecture model or the\n\
         // Lean specification, then re-plan, re-approve and regenerate.\n"
    )
}

/// Renders `text` as `//!` inner doc lines (blank lines preserved).
pub fn inner_doc(text: &str) -> String {
    prefixed("//!", text)
}

fn prefixed(prefix: &str, text: &str) -> String {
    let mut out = String::new();
    for line in text.lines() {
        if line.is_empty() {
            out.push_str(prefix);
        } else {
            out.push_str(prefix);
            out.push(' ');
            out.push_str(line);
        }
        out.push('\n');
    }
    out
}

/// `request_latch` → `RequestLatch`.
pub fn type_name(identifier: &str) -> String {
    identifier
        .split('_')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars
                .next()
                .map(|c| c.to_ascii_uppercase().to_string() + chars.as_str())
                .unwrap_or_default()
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn doc_lines_keep_blank_lines_without_trailing_spaces() {
        assert_eq!(inner_doc("a\n\nb"), "//! a\n//!\n//! b\n");
    }

    #[test]
    fn type_names() {
        assert_eq!(type_name("request_latch"), "RequestLatch");
        assert_eq!(type_name("signal"), "Signal");
    }
}
